function sharedPrefixCounts(a: number[], b: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < a.length; i++) {
    const inA = new Set(a.slice(0, i + 1));
    let c = 0;
    for (let j = 0; j <= i; j++) if (inA.has(b[j])) c++;
    out.push(c);
  }
  return out;
}

