function sharedPrefixCounts(a: number[], b: number[]): number[] {
  const seen = new Array(a.length + 1).fill(0);
  const out: number[] = [];
  let total = 0;
  for (let i = 0; i < a.length; i++) {
    if (++seen[a[i]] === 2) total++;
    if (++seen[b[i]] === 2) total++;
    out.push(total);
  }
  return out;
}

