class Solution:
    def sharedPrefixCounts(self, a: List[int], b: List[int]) -> List[int]:
        seen = [0] * (len(a) + 1)
        out, total = [], 0
        for x, y in zip(a, b):
            seen[x] += 1
            if seen[x] == 2:
                total += 1
            seen[y] += 1
            if seen[y] == 2:
                total += 1
            out.append(total)
        return out

